3	// =============================================================================
4	// Masking text line reveal.
5	// The wrapper clips overflow and the line handles movement, opacity, and blur.
6	// Multi-line content is split by TS into sibling .masking-text blocks and
7	// staggered below via adjacent sibling selectors.
8	// =============================================================================
9	
10	@mixin text-reveal-line-hidden {
11	  transform: translate3d(0, var(--text-reveal-offset-y), 0);
12	  opacity: 0;
13	  filter: blur(var(--text-reveal-blur));
14	}
15	
16	@mixin text-reveal-line-visible {
17	  transform: translate3d(0, 0, 0);
18	  opacity: 1;
19	  filter: blur(0);
20	}
21	
22	@mixin text-reveal-line-down {
23	  transform: translate3d(0, var(--text-reveal-down-offset-y), 0);
24	  opacity: 0;
25	  filter: blur(var(--text-reveal-down-blur));
26	}
27	
28	.mask-target {
29	  opacity: 0;
30	  visibility: hidden;
31	
32	  &.is-mask-ready {
33	    opacity: 1;
34	    visibility: visible;
35	  }
36	}
37	
38	.is-text-reveal-disabled {
39	  .mask-target {
40	    opacity: 0;
41	    visibility: hidden;
42	  }
43	
44	  .masking-text {
45	    opacity: 0;
46	    visibility: hidden;
47	
48	    .masking-text__line,
49	    .line {
50	      @include text-reveal-line-hidden();
51	      transition: none;
52	    }
53	  }
54	}
55	
56	.masking-text {
57	  display: block;
58	  overflow: hidden;
59	  opacity: 1;
60	  visibility: visible;
61	  transition:
62	    opacity var(--transition-base),
63	    visibility var(--transition-base);
64	
65	  .masking-text__line,
66	  .line {
67	    display: block;
68	    position: relative;
69	    text-align: start;
70	    @include text-reveal-line-hidden();
71	    transition:
72	      transform var(--transition-slow),
73	      opacity var(--transition-slow),
74	      filter var(--transition-slow);
75	    will-change: transform, opacity, filter;
76	  }
77	
78	  &:not(.is-hidden).is-inview .masking-text__line,
79	  &:not(.is-hidden).is-inview .line,
80	  &:not(.is-hidden).is-visible .masking-text__line,
81	  &:not(.is-hidden).is-visible .line {
82	    @include text-reveal-line-visible();
83	  }
84	
85	  &.is-down {
86	    opacity: 1;
87	    visibility: visible;
88	
89	    .masking-text__line,
90	    .line {
91	      @include text-reveal-line-down();
92	      transition-duration: var(--duration-slower);
93	      transition-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
94	    }
95	  }
96	
97	  &.is-hidden {
98	    opacity: 0;
99	    visibility: hidden;
100	
101	    .masking-text__line,
102	    .line {
103	      @include text-reveal-line-hidden();
104	    }
105	  }
106	}
107	
108	// Multi-line stagger.
109	
110	.masking-text + .masking-text {
111	  .masking-text__line,
112	  .line {
113	    transition-delay: var(--duration-stagger);
114	  }
115	}
116	
117	.masking-text + .masking-text + .masking-text {
118	  .masking-text__line,
119	  .line {
120	    transition-delay: calc(var(--duration-stagger) * 2);
121	  }
122	}
123	
124	.masking-text + .masking-text + .masking-text + .masking-text {
125	  .masking-text__line,
126	  .line {
127	    transition-delay: calc(var(--duration-stagger) * 3);
128	  }
129	}
130	
131	.masking-text + .masking-text + .masking-text + .masking-text + .masking-text {
132	  .masking-text__line,
133	  .line {
134	    transition-delay: calc(var(--duration-stagger) * 4);
135	  }
136	}
