2	import type {
3	  RevealObserveOptions,
4	  TextRevealOptions,
5	  TextRevealInitOptions,
6	} from "../types/component.types.js";
7	import { DOM_CONFIG, MASKING } from "../config/dom.config.js";
8	import { ObserveManager } from "../manager/ObserveManager.js";
9	import { Animation } from "./Animation.js";
10	
11	const BR_PATTERN = /<br\s*\/?>/gi;
12	const MASKING_DISABLED_CLASS = "is-text-reveal-disabled";
13	
14	export class TextReveal extends Animation {
15	  private static readonly MASK_READY_CLASS = "is-mask-ready";
16	  private static _observeFrameId: number | null = null;
17	  private static readonly _observeManager = new ObserveManager();
18	
19	  static riseUp(
20	    target: string | Element | Element[],
21	    options: TextRevealOptions = {},
22	  ): void {
23	    const revealClass = options.revealClass ?? MASKING.inviewClass;
24	    const elements = TextReveal.resolveManagedElements(target).filter(
25	      (element): element is HTMLElement =>
26	        element instanceof HTMLElement && !element.classList.contains(revealClass),
27	    );
28	    if (elements.length === 0) return;
29	    elements.forEach((element) => {
30	      element.classList.remove(MASKING.downClass);
31	      element.classList.remove(MASKING.hiddenClass);
32	      element.classList.add(revealClass);
33	    });
34	  }
35	
36	  static setVisibleOn(
37	    target: string | Element | Element[],
38	    options: TextRevealOptions = {},
39	  ): void {
40	    TextReveal.riseUp(target, options);
41	  }
42	
43	  static setVisibleOff(
44	    target: string | Element | Element[],
45	    options: TextRevealOptions = {},
46	  ): void {
47	    const revealClass = options.revealClass ?? MASKING.inviewClass;
48	    const elements = TextReveal.resolveManagedElements(target).filter(
49	      (element): element is HTMLElement => element instanceof HTMLElement,
50	    );
51	    if (elements.length === 0) return;
52	    elements.forEach((element) => {
53	      element.classList.remove(revealClass, MASKING.visibleClass);
54	      element.classList.remove(MASKING.hiddenClass);
55	      element.classList.remove(MASKING.downClass);
56	      void element.getBoundingClientRect();
57	      element.classList.add(MASKING.downClass);
58	    });
59	  }
60	
61	  static prepare(
62	    target: string | Element | Element[],
63	    options: TextRevealOptions = {},
64	  ): Element[] {
65	    const revealClass = options.revealClass ?? MASKING.inviewClass;
66	    const elements = TextReveal.resolveManagedElements(target).filter(
67	      (element): element is HTMLElement => element instanceof HTMLElement,
68	    );
69	    if (elements.length === 0) return [];
70	    elements.forEach((element) => {
71	      element.classList.remove(
72	        revealClass,
73	        MASKING.visibleClass,
74	        MASKING.downClass,
75	      );
76	    });
77	    return elements;
78	  }
79	
80	  static observe(
81	    target: string | Element | Element[],
82	    options: RevealObserveOptions = {},
83	  ): void {
84	    if (typeof document === "undefined") return;
85	    const revealClass = options.inviewClass ?? MASKING.inviewClass;
86	    const targets = TextReveal._resolveObserveTargets(target, options);
87	    if (targets.length === 0) return;
88	    const onEnter =
89	      options.onEnter ??
90	      ((element: Element) =>
91	        TextReveal.riseUp(element, { revealClass }));
92	    if (TextReveal._observeFrameId != null) {
93	      window.cancelAnimationFrame(TextReveal._observeFrameId);
94	    }
95	    TextReveal._observeFrameId = window.requestAnimationFrame(() => {
96	      TextReveal._observeFrameId = window.requestAnimationFrame(() => {
97	        TextReveal._observeFrameId = null;
98	        TextReveal._observeManager.observe(
99	          targets,
100	          {
101	            onEnter,
102	            onLeave: options.onLeave,
103	          },
104	          options,
105	        );
106	      });
107	    });
108	  }
109	
110	  static override resolveElements(
111	    target: string | Element | Element[],
112	  ): Element[] {
113	    if (target == null) return [];
114	    const resolve = (el: Element | null | undefined): Element[] => {
115	      if (el == null || typeof el.matches !== "function") return [];
116	      if (el.matches(MASKING.selector)) return [el];
117	      return [el, ...Array.from(el.querySelectorAll<Element>(MASKING.selector))];
118	    };
119	
120	    if (typeof target === "string") {
121	      const list = document.querySelectorAll(target);
122	      return Array.from(list).flatMap(resolve);
123	    }
124	    const arr = super.resolveElements(target);
125	    return arr.flatMap(resolve);
126	  }
127	
128	  static wrap(
129	    selector = `.${MASKING.wrapTargetClass}`,
130	    root?: ParentNode | null,
131	  ): void {
132	    if (typeof document === "undefined") return;
133	    const wrapperClass = MASKING.selector.slice(1);
134	    const scope = root ?? document;
135	    const elements = scope.querySelectorAll<HTMLElement>(selector);
136	    elements.forEach((el) => {
137	      if (el.querySelector(MASKING.selector)) {
138	        el.classList.add(TextReveal.MASK_READY_CLASS);
139	        return;
140	      }
141	      const hasBr = el.querySelector("br") !== null;
142	      if (hasBr) {
143	        TextReveal.wrapMultiLine(el, wrapperClass);
144	      } else {
145	        TextReveal.wrapSingleLine(el, wrapperClass);
146	      }
147	      el.classList.add(TextReveal.MASK_READY_CLASS);
148	    });
149	  }
150	
151	  private static wrapSingleLine(el: HTMLElement, wrapperClass: string): void {
152	    const outer = document.createElement("span");
153	    outer.className = wrapperClass;
154	    const inner = document.createElement("span");
155	    inner.className = MASKING.lineClass;
156	    while (el.firstChild) inner.appendChild(el.firstChild);
157	    outer.appendChild(inner);
158	    el.appendChild(outer);
159	  }
160	
161	  private static wrapMultiLine(el: HTMLElement, wrapperClass: string): void {
162	    const segments = el.innerHTML
163	      .split(BR_PATTERN)
164	      .map((s) => s.trim())
165	      .filter(Boolean);
166	    el.innerHTML = "";
167	    segments.forEach((segmentHtml) => {
168	      const outer = document.createElement("span");
169	      outer.className = wrapperClass;
170	      const inner = document.createElement("span");
171	      inner.className = MASKING.lineClass;
172	      inner.innerHTML = segmentHtml;
173	      outer.appendChild(inner);
174	      el.appendChild(outer);
175	    });
176	  }
177	
178	  
179	
180	
181	
182	  static init(options: TextRevealInitOptions = {}): void {
183	    if (typeof document === "undefined") return;
184	
185	    TextReveal.dispose();
186	
187	    TextReveal.wrap(`.${MASKING.wrapTargetClass}`, options.root);
188	    if (!MASKING.enabled) {
189	      document.documentElement.classList.add(MASKING_DISABLED_CLASS);
190	      return;
191	    }
192	    document.documentElement.classList.remove(MASKING_DISABLED_CLASS);
193	
194	    const selector = options.selector ?? MASKING.selector;
195	    const excludeSelectors =
196	      options.excludeSelectors ?? DOM_CONFIG.maskingExcludeSelectors ?? [];
197	    const inviewClass = options.inviewClass ?? MASKING.inviewClass;
198	    const targets = TextReveal.resolveTargets(
199	      selector,
200	      excludeSelectors,
201	      options.root,
202	    );
203	    if (targets.length === 0) return;
204	    TextReveal.prepare(targets, { revealClass: inviewClass });
205	    TextReveal.observe(targets, { ...options, inviewClass });
206	  }
207	
208	  static dispose(): void {
209	    if (TextReveal._observeFrameId != null) {
210	      window.cancelAnimationFrame(TextReveal._observeFrameId);
211	      TextReveal._observeFrameId = null;
212	    }
213	    TextReveal._observeManager.dispose();
214	    if (typeof document !== "undefined") {
215	      document.documentElement.classList.remove(MASKING_DISABLED_CLASS);
216	    }
217	  }
218	
219	  private static resolveTargets(
220	    selector: string,
221	    excludeSelectors: string[],
222	    root?: ParentNode | null,
223	  ): Element[] {
224	    const scope = root ?? document;
225	    const all = Array.from(scope.querySelectorAll(selector));
226	    const excludeRoots = excludeSelectors
227	      .map((sel) => scope.querySelector(sel))
228	      .filter((el): el is Element => el != null);
229	    const scoped =
230	      excludeRoots.length === 0
231	        ? all
232	        : all.filter((el) =>
233	      excludeRoots.every((root) => !root.contains(el)),
234	    );
235	    return [...new Set(scoped)];
236	  }
237	
238	  private static resolveManagedElements(
239	    target: string | Element | Element[],
240	  ): Element[] {
241	    if (typeof document === "undefined") return [];
242	    if (!MASKING.enabled) return [];
243	    if (target == null) return [];
244	    return TextReveal.resolveElements(target);
245	  }
246	
247	  private static _resolveObserveTargets(
248	    target: string | Element | Element[],
249	    options: RevealObserveOptions,
250	  ): Element[] {
251	    if (typeof target !== "string") {
252	      return TextReveal.resolveManagedElements(target);
253	    }
254	    const excludeSelectors =
255	      options.excludeSelectors ?? DOM_CONFIG.maskingExcludeSelectors ?? [];
256	    return TextReveal.resolveTargets(target, excludeSelectors, options.root);
257	  }
258	}
