1	@use "sass:map";
2	@use "sass:math";
3	@use "sass:meta";
4	@use "sass:string";
5	
6	@use "./variables" as var;
7	
8	@use "./functions" as func;
9	
10	@use "./headings" as heading;
11	
12	@mixin mq($key-or-size, $direction: "max") {
13	  @if (meta.type-of($key-or-size) == "string") {
14	    $size: map.get(var.$containers, $key-or-size);
15	
16	    @media (#{$direction}-width: #{$size}px) {
17	      @content;
18	    }
19	  } @else if (meta.type-of($key-or-size) == "number") {
20	    @media (#{$direction}-width: #{$key-or-size}px) {
21	      @content;
22	    }
23	  } @else {
24	    @error "No found breakpoint: #{$key-or-size}";
25	  }
26	}
27	
28	@mixin pos-full() {
29	  position: absolute;
30	
31	  top: 0;
32	
33	  left: 0;
34	
35	  width: 100%;
36	
37	  height: 100%;
38	}
39	
40	@mixin pos-center() {
41	  position: absolute;
42	
43	  top: 50%;
44	
45	  left: 50%;
46	
47	  transform: translate(-50%, -50%);
48	
49	  width: 100%;
50	
51	  height: 100%;
52	}
53	
54	@mixin set-fluid($map) {
55	  @each $key, $val in $map {
56	    $min: map.get($val, "min");
57	    $max: map.get($val, "max");
58	
59	    #{$key}: #{func.fluid($min, $max)};
60	  }
61	}
62	
63	@mixin section-fluid-by-map($map) {
64	  $min: map.get($map, "min");
65	
66	  $max: map.get($map, "max");
67	
68	  $max-w: map.get($map, "max-width");
69	
70	  $min-w: map.get($map, "min-width");
71	
72	  padding-bottom: #{func.fluid($min, $max, $min-w, $max-w)};
73	
74	  padding-top: #{func.fluid($min, $max, $min-w, $max-w)};
75	}
76	
77	@mixin fs-static-by-map($map) {
78	  $base: map.get($map, "base");
79	
80	  $fw: map.get($map, "fw");
81	
82	  $lh: map.get($map, "lh");
83	
84	  $ls: map.get($map, "ls");
85	
86	  $ff: map.get($map, "ff");
87	
88	  @if ($base != null) {
89	    font-size: func.pxToRem($base);
90	  }
91	
92	  @if ($fw != null) {
93	    font-weight: $fw;
94	  }
95	
96	  @if ($lh != null) {
97	    line-height: $lh;
98	  }
99	  @if ($ff != null) {
100	    font-family: $ff;
101	  }
102	
103	  @if ($ls != null) {
104	    letter-spacing: func.pxToRem($ls);
105	  }
106	
107	  @each $con-key, $con-val in var.$containers {
108	    $breakpoint: map.get($map, $con-key);
109	
110	    @if ($breakpoint != null) {
111	      @include mq($con-key) {
112	        font-size: func.pxToRem($breakpoint);
113	      }
114	    }
115	  }
116	}
117	
118	@mixin fs-fluid-by-map($map) {
119	  $min: map.get($map, "min");
120	
121	  $max: map.get($map, "max");
122	
123	  $max-w: map.get($map, "max-width");
124	
125	  $min-w: map.get($map, "min-width");
126	
127	  $lh: map.get($map, "lh");
128	
129	  $fw: map.get($map, "fw");
130	
131	  $ls: map.get($map, "ls");
132	
133	  $ff: map.get($map, "ff");
134	
135	  font-size: #{func.fluid($min, $max, $min-w, $max-w)};
136	
137	  @if ($lh != null) {
138	    line-height: $lh;
139	  }
140	
141	  @if ($fw != null) {
142	    font-weight: $fw;
143	  }
144	
145	  @if ($ls != null) {
146	    letter-spacing: func.pxToRem($ls);
147	  }
148	
149	  @if ($ff != null) {
150	    font-family: $ff;
151	  }
152	}
153	
154	@mixin fs-fluid($min, $max, $min-width: null, $max-width: null) {
155	  font-size: #{func.fluid($min, $max, $min-width, $max-width)};
156	}
157	
158	@mixin fs-static($fs, $key: "null") {
159	  @if ($key == "null") {
160	    font-size: $fs;
161	  } @else {
162	    @include mq($key) {
163	      font-size: $fs;
164	    }
165	  }
166	}
167	
168	@mixin mq-max($key-or-size) {
169	  @include mq($key-or-size, "max") {
170	    @content;
171	  }
172	}
173	
174	@mixin mq-min($key-or-size) {
175	  @include mq($key-or-size, "min") {
176	    @content;
177	  }
178	}
