180	@mixin flex-center() {
181	  display: flex;
182	
183	  align-items: center;
184	
185	  justify-content: center;
186	}
187	
188	@mixin blind() {
189	  position: absolute;
190	
191	  clip: rect(0 0 0 0);
192	
193	  width: 1px;
194	
195	  height: 1px;
196	
197	  margin: -1px;
198	
199	  overflow: hidden;
200	}
201	
202	@mixin line-clamp($line) {
203	  overflow: hidden;
204	
205	  text-overflow: ellipsis;
206	
207	  -webkit-box-orient: vertical;
208	
209	  display: -webkit-box;
210	
211	  -webkit-line-clamp: $line;
212	}
213	
214	@mixin img-cover() {
215	  width: 100%;
216	
217	  height: 100%;
218	
219	  object-fit: cover;
220	}
221	
222	@mixin img-auto-cover($percent: 56.25%) {
223	  position: relative;
224	
225	  overflow: hidden;
226	
227	  height: 0;
228	
229	  padding-bottom: $percent;
230	
231	  img {
232	    @include pos-full();
233	
