238	@mixin backdrop($opacity: 0.45) {
239	  @include pos-full();
240	
241	  background: rgba(0, 0, 0, $opacity);
242	}
243	
244	/// @deprecated 코너는 실 요소(components/corner-bracket partial + .no-corner-bracket)로 통일. 마그네틱 코너와 동일 8-path SVG 형식 사용.
245	@mixin corner-bracket(
246	  $inset: -2px,
247	  $padding: 2px,
248	  $border-color: var(--clr-border-strong),
249	  $cut-size: 10px
250	) {
251	  content: "";
252	  position: absolute;
253	  box-sizing: border-box;
254	  inset: $inset;
255	  padding: $padding;
256	  border: 2px solid $border-color;
257	  background: transparent content-box;
258	  mask:
259	    conic-gradient(#000 0 0) content-box,
260	    conic-gradient(at #{$cut-size} #{$cut-size}, #0000 75%, #000 0) 0 0 /
261	      calc(100% - #{$cut-size}) calc(100% - #{$cut-size});
262	  -webkit-mask:
263	    conic-gradient(#000 0 0) content-box,
264	    conic-gradient(at #{$cut-size} #{$cut-size}, #0000 75%, #000 0) 0 0 /
265	      calc(100% - #{$cut-size}) calc(100% - #{$cut-size});
266	  mask-composite: exclude;
267	  -webkit-mask-composite: xor;
268	  backface-visibility: hidden;
269	  pointer-events: none;
270	}
271	
272	/// @deprecated 실 요소 코너 사용 시 transition은 해당 컴포넌트 SCSS에서 지정.
273	@mixin corner-bracket-motion() {
274	  transition:
275	    inset var(--transition-default),
276	    padding var(--transition-default),
277	    border-color var(--transition-default);
278	  will-change: inset, padding;
279	}
280	
281	/// @deprecated 실 요소 코너 사용 시 hover/focus 스타일은 해당 컴포넌트 SCSS에서 .no-corner-bracket 등으로 지정.
282	@mixin corner-bracket-hover(
283	  $inset: -8px,
284	  $padding: 8px,
285	  $border-color: var(--clr-trigger-default)
286	) {
287	  inset: $inset;
288	  padding: $padding;
289	  border-color: $border-color;
290	}
291	
292	@mixin font($name) {
293	  $without-prefix: string.slice($name, 3);
294	  $last-dash-idx: 0;
295	
296	  @for $i from 1 through string.length($without-prefix) {
297	    @if string.slice($without-prefix, $i, $i) == "-" {
298	      $last-dash-idx: $i;
299	    }
300	  }
301	
302	  $category: string.slice($without-prefix, 1, $last-dash-idx - 1);
303	  $key: string.slice($without-prefix, $last-dash-idx + 1);
304	
305	  $type-map: map.get(heading.$fluid-typography, $category);
306	
307	  @if ($type-map == null) {
308	    @error "Unknown font category '#{$category}' in '#{$name}'";
